def filter_data(data, field, value):
    return [item for item in data if item.get(field) == value]

def sort_data(data, key=None, reverse=False):
    return sorted(data, key=lambda x: x.get(key), reverse=reverse)

def group_data(data, field):
    groups = {}
    for item in data:
        k = item.get(field)
        groups.setdefault(k, []).append(item)
    return groups

def aggregate_data(data, field, func):
    values = [item.get(field, 0) for item in data]
    if func == 'sum':
        return sum(values)
    elif func == 'avg':
        return sum(values) / len(values) if values else 0
    elif func == 'min':
        return min(values) if values else None
    elif func == 'max':
        return max(values) if values else None
    else:
        raise ValueError(f'Unknown aggregation function: {func}')

class DataProcessor:
    def process(self, data, operation, extra=None):
        if operation == 'filter':
            return filter_data(data, *extra.get('field'), *extra.get('value', ()))
        elif operation == 'sort':
            return sort_data(data, *extra.get('key', ()), *extra.get('reverse', ()))
        elif operation == 'group':
            return group_data(data, *extra.get('field', ()))
        elif operation == 'aggregate':
            return aggregate_data(data, *extra.get('field', ()), *extra.get('func', ('sum',)))
        else:
            raise ValueError(f'Unknown operation: {operation}')
